# region: fold
def fold(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: gather
def gather(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: shape
def shape(summary, name='beta'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return shape(sift(emit(render(gather(fold(raw))))))

