        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'total': 61, 'label': 'BETA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'total': 389, 'label': 'BETA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 2, 'total': 194, 'label': 'BETA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'total': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'total': 1345, 'label': 'BETA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'total': 0, 'label': 'EMPTY'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 1080, 'label': 'BETA'})
